      if (/(صيدليه|دوا|علاج|روشته|بانادول|فيتامين)/.test(context)) return "\u0635\u064A\u062F\u0644\u064A\u0629";
      if (/(تحاليل|اشعه|سونار|رنين)/.test(context)) return "\u062A\u062D\u0627\u0644\u064A\u0644";
