    auth_token: authToken,
    amount_cents: amountCents,
    expiration: 3600,
    order_id: order.id,
    billing_data: billingData,
    currency: "EGP",
    integration_id: Number(env.PAYMOB_INTEGRATION_ID),
    lock_order_when_paid: true,
